scripts.script:
game.StarterGui:SetCore("SendNotification", {
    Title = "Get All Tool";
    Text = "I still find a way to bypass The Tool, May not work at all";
    Icon = "rbxassetid://6031075938";
    Duration = 100;
    Button1 = "Thanks";      
    Button2 = "Ok I will wait";        
    Callback = callback;        
})

local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Players = game:GetService("Players")

local toolsFolder = ReplicatedStorage:WaitForChild("Tools")


local function giveToolsToPlayer(player)
	local backpack = player:WaitForChild("Backpack")

	for _, tool in ipairs(toolsFolder:GetChildren()) do
		if tool:IsA("Tool") then
			tool:Clone().Parent = backpack
		end
	end
end


Players.PlayerAdded:Connect(function(player)
	player.CharacterAdded:Connect(function()
		task.wait(0.5) 
		giveToolsToPlayer(player)
	end)


	if player.Character then
		task.wait(0.5)
		giveToolsToPlayer(player)
	end
end)


for _, player in ipairs(Players:GetPlayers()) do
	if player.Character then
		task.wait(0.5)
		giveToolsToPlayer(player)
	end
end
